if (window.top !== window) return;
const hidden = new Set();
const sweep = () => {
  for (const header of document.querySelectorAll('.feed-shared-update-v2 .update-components-header')) {
    if (!header.textContent.trim().startsWith('Suggested')) continue;
    const post = header.closest('.feed-shared-update-v2');
    if (post && !hidden.has(post)) { post.style.display = 'none'; hidden.add(post); }
  }
};
const timer = setInterval(sweep, 1000);
(window[Symbol.for('openmedia.cleanup')] ||= []).push(() => {
  clearInterval(timer);
  for (const post of hidden) post.style.removeProperty('display');
  hidden.clear();
});
sweep();
